/*
 * SMS Connector: Provider Abstraction Boundary Documentation & Tests
 *
 * ## Overview
 * Posnic defines a robust provider abstraction boundary for SMS integrations to
 * support multiple SMS gateways cleanly while maintaining strict privacy boundaries
 * and safety guarantees.
 *
 * ## Common SMS Provider Inputs
 * Every SMS provider connector must accept a standardized payload structure:
 * - `destination`: Recipient phone number (E.164 formatted string, e.g., "+15555550199").
 * - `message` / `template`: Text content or template identifier with variable bindings.
 * - `senderId`: Approved alphanumeric or numeric sender ID or originator string.
 * - `statusCallback`: Webhook URL or function reference for delivery status notifications.
 * - `metadata`: Cost tracking, carrier routing, and error diagnostic information.
 *
 * ## Privacy and Opt-In Boundaries
 * Customer phone numbers are classified as sensitive PII.
 * - **Opt-In Enforcement**: SMS messages must only be dispatched if the customer record
 *   explicitly sets `sms_opt_in: true`. Unsolicited or opt-out messages are blocked.
 * - **Masking & Logging**: Phone numbers must be masked in application logs (e.g., "+1****-0199")
 *   to prevent leakage in centralized log management systems.
 * - **Retention**: Phone numbers must be scrubbed upon formal GDPR/privacy erasure requests.
 *
 * ## Fake SMS Provider Fixture for Tests
 * To facilitate unit and integration testing without incurring costs or external dependencies,
 * Posnic provides a standard in-memory fake SMS provider fixture (`FakeSmsProvider`).
 *
 * ## Default Safety Guarantee
 * **No real SMS is sent by default.** In the absence of an explicitly configured and enabled
 * production SMS connector plugin, all SMS dispatches are intercepted and routed to the
 * safe local logger / fake fixture.
 */
describe('SMS connector abstraction boundary documentation and fixture', () => {
  class FakeSmsProvider {
    constructor() {
      this.outbox = [];
      this.sentCount = 0;
    }
    async send(payload) {
      if (!payload.sms_opt_in) {
        throw new Error('Privacy violation: customer has not opted in for SMS');
      }
      this.outbox.push({
        destination: payload.destination,
        message: payload.message || payload.template,
        senderId: payload.senderId || 'POSNIC',
        statusCallback: payload.statusCallback || null,
        metadata: { cost: 0.01, currency: 'USD', status: 'queued', error: null },
        timestamp: new Date().toISOString()
      });
      this.sentCount++;
      return { success: true, messageId: 'fake_msg_' + this.sentCount };
    }
  }

  test('FakeSmsProvider captures messages when opted in and blocks when not', async () => {
    const provider = new FakeSmsProvider();

    // Opt-in check passes
    const result = await provider.send({
      destination: '+15555550199',
      message: 'Your order is ready',
      sms_opt_in: true
    });
    expect(result.success).toBe(true);
    expect(provider.outbox.length).toBe(1);
    expect(provider.outbox[0].destination).toBe('+15555550199');
    expect(provider.outbox[0].metadata).toHaveProperty('cost');

    // Opt-in check blocks
    await expect(
      provider.send({
        destination: '+15555550199',
        message: 'Unsolicited offer',
        sms_opt_in: false
      })
    ).rejects.toThrow(/opted in/);
  });

  test('default safety guarantee ensures no real SMS is sent without explicit provider', () => {
    const activeProvider = null; // Default state
    const dispatchAttempt = (provider, payload) => {
      if (!provider) {
        return { dispatched: false, reason: 'No real SMS sent by default' };
      }
      return { dispatched: true };
    };
    const res = dispatchAttempt(activeProvider, { destination: '+15555550199' });
    expect(res.dispatched).toBe(false);
    expect(res.reason).toMatch(/No real SMS sent by default/);
  });
});
