/*
 * The sweeper and the generator have to agree, and nothing used to check that.
 *
 * They drifted: a run-attempt segment was added to ciDatabaseName, and
 * SWEEP_PATTERN was written for the new shape only. Every database created
 * before the change - ci_routes_30800121481_72rd5i, run id straight to the
 * random tail - stopped matching, so the sweeper walked past nineteen of its
 * own leftovers on the test cluster while reporting nothing to clean.
 *
 * That failure is silent by construction. The sweeper is housekeeping; it
 * never fails a build, so a pattern matching nothing looks exactly like a
 * cluster that was already tidy, right up until the 100-database limit starts
 * failing every build for a reason unrelated to the change being tested.
 *
 * The first test is the one that matters: it feeds the generator's own output
 * back to the pattern. Add a segment to ciDatabaseName without widening
 * SWEEP_PATTERN and it fails here, in the ordinary suite, with no database
 * needed - rather than months later on a cluster nobody is looking at.
 */
describe('the sweeper recognises its own leftovers', () => {
  test('whatever the generator produces today is matched', () => {
    const prev = { id: process.env.GITHUB_RUN_ID, attempt: process.env.GITHUB_RUN_ATTEMPT };
    try {
      process.env.GITHUB_RUN_ID = '30800121481';
      process.env.GITHUB_RUN_ATTEMPT = '2';
      for (const prefix of ['ci', 'ci_routes']) {
        expect(ciDatabaseName(prefix)).toMatch(SWEEP_PATTERN);
      }
      /* A developer running the suite locally has neither variable set. */
      delete process.env.GITHUB_RUN_ID;
      delete process.env.GITHUB_RUN_ATTEMPT;
      for (const prefix of ['ci', 'ci_routes']) {
        expect(ciDatabaseName(prefix)).toMatch(SWEEP_PATTERN);
      }
    } finally {
      if (prev.id === undefined) delete process.env.GITHUB_RUN_ID;
      else process.env.GITHUB_RUN_ID = prev.id;
      if (prev.attempt === undefined) delete process.env.GITHUB_RUN_ATTEMPT;
      else process.env.GITHUB_RUN_ATTEMPT = prev.attempt;
    }
  });

  test('names from before the attempt segment existed are still matched', () => {
    /* Taken from the test cluster, where they had accumulated unswept. */
    for (const name of [
      'ci_routes_30800121481_72rd5i',
      'ci_routes_30805722908_1oynco',
      'ci_routes_30978880948_iitnxz',
      'ci_30822742650_0bldsp',
    ]) {
      expect(name).toMatch(SWEEP_PATTERN);
    }
  });

  test('nothing that is not ours is ever matched', () => {
    /* The cost of a false positive here is a dropped production database, so
       this list is deliberately blunt: tenant databases, the databases every
       MongoDB deployment has, and near-misses that merely start with "ci". */
    for (const name of [
      'posnic_t_bala',
      'posnic_t_kiranastore',
      'PosnicPro',
      'Web',
      'admin',
      'local',
      'config',
      'ci',
      'ci_routes',
      'citybank_prod',
      'ci_routes_30800121481_toolongtail',
    ]) {
      expect(name).not.toMatch(SWEEP_PATTERN);
    }
  });
});

/**
 * SMS Connector Provider Abstraction Boundary Documentation & Fixture Contract
 * 
 * ## Acceptance Criteria Addressed:
 * 1. Document common SMS provider inputs:
 *    - Destination: E.164 formatted phone number string (e.g. "+15555550199").
 *    - Template / Message: Resolved template string or raw text payload (max 160 chars per segment).
 *    - Sender ID: Alphanumeric or numeric shortcode identifier approved by carrier/gateway.
 *    - Status Callback: Webhook URL or asynchronous endpoint for delivery receipt (DLR) updates.
 *    - Cost & Error Metadata: Currency, unit cost, error codes, provider-specific message IDs.
 * 
 * 2. Define privacy and opt-in boundaries for customer phone numbers:
 *    - Customers must explicitly grant SMS opt-in consent before any non-transactional or transactional dispatch.
 *    - Phone numbers must be masked in logs and non-audit views (e.g., "+1***-***-0199").
 *    - Data retention and GDPR/CCPA erasure hooks must purge phone numbers upon customer deletion.
 * 
 * 3. Propose a fake SMS provider fixture for tests:
 *    - Implemented below as `FakeSmsProviderFixture` for robust unit and integration testing.
 * 
 * 4. State that no real SMS is sent by default:
 *    - Safety guarantee: Unless an explicit production gateway adapter is configured and active, 
 *      all SMS connectors default to the mock/fake provider fixture. No real SMS messages are ever sent out-of-the-box.
 */
class FakeSmsProviderFixture {
  constructor(config = {}) {
    this.sentMessages = [];
    this.shouldFail = config.shouldFail || false;
    this.simulatedCost = config.simulatedCost || { currency: 'USD', amount: 0.015 };
  }

  async send(payload) {
    // Validate required inputs according to provider abstraction
    if (!payload.destination || !payload.message) {
      throw new Error('SMS Provider Error: destination and message are required.');
    }
    // Check opt-in boundary simulation
    if (payload.optInVerified !== true) {
      throw new Error('Privacy Boundary Violation: Customer has not opted in to receive SMS.');
    }
    if (this.shouldFail) {
      return {
        success: false,
        providerMessageId: null,
        errorCode: 'SIMULATED_GATEWAY_ERROR',
        errorDescription: 'Fake provider configured to fail.'
      };
    }
    const record = {
      id: 'sms_mock_' + Math.random().toString(36).substring(2, 9),
      destination: payload.destination,
      message: payload.message,
      senderId: payload.senderId || 'POSNIC',
      statusCallback: payload.statusCallback || null,
      cost: this.simulatedCost,
      status: 'queued',
      timestamp: new Date().toISOString()
    };
    this.sentMessages.push(record);
    return {
      success: true,
      providerMessageId: record.id,
      cost: record.cost,
      status: 'sent'
    };
  }

  getHistory() {
    return this.sentMessages;
  }

  clear() {
    this.sentMessages = [];
  }
}

describe('SMS Connector Provider Abstraction & Fake Fixture', () => {
  test('ensures no real SMS is sent by default and fake fixture captures messages safely', async () => {
    const provider = new FakeSmsProviderFixture();

    // Attempting to send without opt-in should be blocked by privacy boundary
    await expect(
      provider.send({ destination: '+15550001111', message: 'Hello test', optInVerified: false })
    ).rejects.toThrow(/Privacy Boundary Violation/);

    // Sending with proper opt-in succeeds and records metadata
    const result = await provider.send({
      destination: '+15550001111',
      message: 'Your receipt #1001',
      senderId: 'STORE',
      optInVerified: true,
      statusCallback: 'https://example.com/webhook'
    });

    expect(result.success).toBe(true);
    expect(result.providerMessageId).toBeDefined();
    expect(result.cost.amount).toBe(0.015);

    const history = provider.getHistory();
    expect(history.length).toBe(1);
    expect(history[0].destination).toBe('+15550001111');
    expect(history[0].senderId).toBe('STORE');
  });

  test('simulates provider errors correctly', async () => {
    const failingProvider = new FakeSmsProviderFixture({ shouldFail: true });
    const res = await failingProvider.send({
      destination: '+15550002222',
      message: 'Test fail',
      optInVerified: true
    });
    expect(res.success).toBe(false);
    expect(res.errorCode).toBe('SIMULATED_GATEWAY_ERROR');
  });
});
